'use strict';
const PRODUCTS = [
  {id:'backpack',name:'Everyday Backpack',category:'Bags',price:2490,oldPrice:2990,rating:'4.8',reviews:124,tag:'BESTSELLER',colors:[['Forest','#384536'],['Charcoal','#343838']],sizes:['One size'],stock:8,description:'Go lightly, go anywhere. A compact everyday backpack with thoughtful storage, comfortable straps, and room for the essentials.',material:'Durable woven fabric',detail:'18 L · Padded laptop sleeve'},
  {id:'sneakers',name:'City Runner',category:'Footwear',price:3290,oldPrice:3990,rating:'4.9',reviews:86,tag:'NEW',colors:[['Terracotta','#ad6845'],['Sand','#d0bd9b']],sizes:['UK 6','UK 7','UK 8','UK 9'],stock:6,description:'A softer step for busy days. Lightweight everyday sneakers with a cushioned sole and an effortlessly versatile silhouette.',material:'Breathable textile upper',detail:'Flexible sole · True to size'},
  {id:'headphones',name:'Studio Headphones',category:'Tech',price:4490,oldPrice:4990,rating:'4.7',reviews:73,tag:'',colors:[['Black','#272d2e']],sizes:['One size'],stock:4,description:'Find your focus. Comfortable over-ear headphones for your morning commute, deep work, and everything in between.',material:'Soft ear cushions',detail:'Wireless · Up to 30 hours'},
  {id:'sunglasses',name:'Weekend Frames',category:'Accessories',price:1490,oldPrice:1790,rating:'4.6',reviews:51,tag:'',colors:[['Tortoise','#674534'],['Black','#252628']],sizes:['One size'],stock:10,description:'A little shade, a lot of character. Lightweight frames with a timeless shape for everyday adventures.',material:'Lightweight acetate',detail:'UV400 · Protective pouch'},
  {id:'watch',name:'Essential Watch',category:'Accessories',price:3890,oldPrice:4490,rating:'4.8',reviews:62,tag:'STAFF PICK',colors:[['Brown','#785636'],['Black','#282b29']],sizes:['38 mm','42 mm'],stock:5,description:'Time, thoughtfully told. A clean everyday watch with a comfortable strap and a beautifully simple face.',material:'Stainless steel case',detail:'Quartz · Water resistant'},
  {id:'bag',name:'Daylight Handbag',category:'Bags',price:2790,oldPrice:3290,rating:'4.8',reviews:91,tag:'NEW',colors:[['Caramel','#a47854'],['Black','#292d2a']],sizes:['One size'],stock:7,description:'Meet your everyday companion. A structured handbag with an easy carry handle and space for everything you need.',material:'Smooth vegan leather',detail:'Adjustable strap · Inner pocket'}
];
const KEY='forme-prototype-v1';
const freshState=()=>({cart:[],wishlist:[],orders:[],reviews:[],productReviews:[],theme:'calm',coupon:'',checkout:{},payment:'upi'});
function loadState(){try{const v=JSON.parse(localStorage.getItem(KEY));if(!v)return freshState();return {...freshState(),...v,cart:Array.isArray(v.cart)?v.cart.filter(x=>PRODUCTS.some(p=>p.id===x.id&&p.colors.some(c=>c[0]===x.color)&&p.sizes.includes(x.size))&&Number.isInteger(x.qty)&&x.qty>0):[],wishlist:Array.isArray(v.wishlist)?v.wishlist:[],orders:Array.isArray(v.orders)?v.orders:[],reviews:Array.isArray(v.reviews)?v.reviews:[],productReviews:Array.isArray(v.productReviews)?v.productReviews.filter(r=>PRODUCTS.some(p=>p.id===r.productId)&&Number.isInteger(r.rating)&&r.rating>=1&&r.rating<=5&&typeof r.id==='string'&&typeof r.reviewer==='string'&&typeof r.title==='string'&&typeof r.body==='string'):[],theme:v.theme==='bold'?'bold':'calm'};}catch{return freshState();}}
let state=loadState(), detailOptions={}, shop={q:'',category:'All',sort:'featured'}, checkoutStep='address', busy=false, toastTimer, lastRenderedRoute='';
const app=document.getElementById('app'),phone=document.getElementById('phone');
const escapeHtml=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'₹'+Math.round(n).toLocaleString('en-IN');
const product=id=>PRODUCTS.find(p=>p.id===id);
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('Browser storage is unavailable. Keep this tab open to retain your session.');}}
function toast(message){clearTimeout(toastTimer);const t=document.getElementById('toast');t.textContent=message;t.classList.add('visible');toastTimer=setTimeout(()=>t.classList.remove('visible'),3500);}
const svgPaths={home:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>',shop:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',bag:'<path d="M4 7h16l1 14H3z"/><path d="M8 8V6a4 4 0 0 1 8 0v2"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',back:'<path d="m14 5-7 7 7 7"/>',reviews:'<path d="M4 4h16v12H9l-5 4z"/><path d="M8 8h8M8 12h5"/>',orders:'<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M9 8h6M9 12h6M9 16h4"/>'};
const icon=name=>`<svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${svgPaths[name]||''}</svg>`;
const cartCount=()=>state.cart.reduce((n,x)=>n+x.qty,0);
const lineKey=x=>`${x.id}|${x.color}|${x.size}`;
function totals(){const subtotal=state.cart.reduce((n,x)=>n+product(x.id).price*x.qty,0);const discount=state.coupon==='FIRST10'?Math.round(subtotal*.1):0;const shipping=subtotal===0||subtotal>=3000?0:79;return{subtotal,discount,shipping,total:subtotal-discount+shipping};}
function header(title,back='home'){return `<header class="phone-header">${title?`<a class="icon-btn" href="#${back}" aria-label="Go back">${icon('back')}</a><h3>${escapeHtml(title)}</h3>`:'<a class="wordmark" href="#home">FORME<span class="brand-dot">®</span></a><span class="eyebrow" style="font-size:8px;letter-spacing:1px">MADE FOR EVERYDAY</span>'}<a href="#cart" class="icon-btn bag-button" aria-label="Shopping bag, ${cartCount()} items">${icon('bag')}${cartCount()?`<span class="bag-count">${cartCount()}</span>`:''}</a></header>`;}
function nav(route){return `<nav class="bottom-nav" aria-label="Main navigation">${[['home','home','Home'],['shop','shop','Shop'],['wishlist','heart','Saved'],['orders','orders','Orders'],['reviews','reviews','Reviews']].map(([href,ico,label])=>`<a href="#${href}" class="${route===href?'active':''}" ${route===href?'aria-current="page"':''}>${icon(ico)}${label}</a>`).join('')}</nav>`;}
function card(p){const saved=state.wishlist.includes(p.id);return `<article class="product-card"><a class="product-image" href="#product/${p.id}" aria-label="View ${p.name}"><img src="assets/${p.id}.jpg" alt="${p.name}" loading="lazy"></a>${p.tag?`<span class="tag">${p.tag}</span>`:''}<button class="heart ${saved?'saved':''}" data-save="${p.id}" aria-label="${saved?'Remove':'Save'} ${p.name}" aria-pressed="${saved}">${saved?'♥':'♡'}</button><a href="#product/${p.id}"><h3>${p.name}</h3></a><div class="category">${p.category} · ${p.colors.length} ${p.colors.length===1?'colour':'colours'}</div><div class="prices">${money(p.price)} <del>${money(p.oldPrice)}</del></div><div class="stars"><span>★</span> ${p.rating} (${p.reviews})</div></article>`;}
const empty=(symbol,title,description,action='Explore the collection',href='shop')=>`<div class="empty"><span class="empty-icon">${symbol}</span><h2>${title}</h2><p>${description}</p>${action==='Clear search & filters'?`<button class="primary" data-action="clear-filters">${action} →</button>`:`<a class="primary" href="#${href}">${action} →</a>`}</div>`;
function searchForm(){return `<form class="search-form" id="search-form"><label class="visually-hidden" for="product-search">Search products</label>${icon('search')}<input id="product-search" name="q" type="search" value="${escapeHtml(shop.q)}" placeholder="Search your next everyday essential"><button type="submit" class="visually-hidden">Search</button></form>`;}
function home(){const bold=state.theme==='bold';return `${bold?'<div class="promo-banner">A little treat: 10% off with FIRST10 ✦</div>':''}<div class="eyebrow">GOOD THINGS, EVERY DAY</div><h1>Find your new<br>everyday favourite.</h1><p class="intro">Considered pieces. Better everyday living.</p>${searchForm()}<section class="hero"><img src="assets/backpack.jpg" alt="Everyday backpack in a natural setting"><div class="hero-content"><div class="eyebrow">${bold?'THE EVERYDAY EDIT · 10% OFF':'THE EVERYDAY EDIT'}</div><h2>${bold?'Good things.<br>Great prices.':'Less, but<br>better.'}</h2><p>Essentials that go wherever life takes you.</p><button data-action="explore">Explore the edit <span>↗</span></button></div></section><div class="trust-strip"><span>↗ Free shipping over ₹3,000</span><span>↻ 14-day returns</span><span>✓ Easy checkout</span></div><div class="section-head"><h3>Made for your everyday</h3><a class="text-button" href="#shop">View all ↗</a></div><div class="product-grid">${PRODUCTS.slice(0,2).map(card).join('')}</div><div class="section-head"><h3>A few more good things</h3></div><div class="product-grid">${PRODUCTS.slice(2).map(card).join('')}</div>`;}
function catalog(){let list=PRODUCTS.filter(p=>(shop.category==='All'||p.category===shop.category)&&`${p.name} ${p.category} ${p.description}`.toLowerCase().includes(shop.q.toLowerCase().trim()));if(shop.sort==='low')list.sort((a,b)=>a.price-b.price);if(shop.sort==='high')list.sort((a,b)=>b.price-a.price);if(shop.sort==='rating')list.sort((a,b)=>+b.rating-+a.rating);return `<div class="eyebrow">YOUR EVERYDAY, CURATED</div><h1>The collection</h1>${searchForm()}<div class="categories" role="group" aria-label="Product categories">${['All','Bags','Footwear','Tech','Accessories'].map(c=>`<button class="chip ${c===shop.category?'active':''}" data-category="${c}" aria-pressed="${c===shop.category}">${c}</button>`).join('')}</div><div class="filters"><span>${list.length} ${list.length===1?'essential':'essentials'}${shop.q?` matching “${escapeHtml(shop.q)}”`:''}</span><label class="visually-hidden" for="sort">Sort products</label><select id="sort">${[['featured','Featured'],['low','Price: low to high'],['high','Price: high to low'],['rating','Top rated']].map(([v,t])=>`<option value="${v}" ${shop.sort===v?'selected':''}>${t}</option>`).join('')}</select></div>${list.length?`<div class="product-grid">${list.map(card).join('')}</div>`:empty('⌕','Nothing here just yet','Try a different search or clear your filters.','Clear search & filters','shop')}`;}
function detail(p){if(!p)return empty('↗','Product not found','Let’s get you back to the collection.');const o=detailOptions[p.id]||{color:p.colors[0][0],size:p.sizes.length===1?p.sizes[0]:''};detailOptions[p.id]=o;return `<img class="product-hero" src="assets/${p.id}.jpg" alt="${p.name}"><div class="detail-badge">${p.tag||'EVERYDAY ESSENTIAL'}</div><div class="detail-title"><h1>${p.name}</h1><div class="prices">${money(p.price)}</div></div><div class="stars"><span>★★★★★</span> ${p.rating} · ${p.reviews} sample ratings</div><a class="text-button product-review-link" href="#reviews/${p.id}">Read & write product reviews (${productReviewsFor(p.id).length}) ↗</a><p class="detail-body">${p.description}</p><div class="option-group"><div class="option-title">Colour · ${escapeHtml(o.color)}</div><div class="swatches">${p.colors.map(([name,color])=>`<button class="swatch ${o.color===name?'active':''}" style="--swatch:${color}" data-color="${name}" aria-label="Choose ${name}" aria-pressed="${o.color===name}"><i></i></button>`).join('')}</div><p class="micro">Photography is illustrative; colour selection is recorded in your bag.</p></div><div class="option-group"><div class="option-title">${p.sizes.length>1?'Choose your size':'Size'}</div><div class="sizes">${p.sizes.map(s=>`<button class="${o.size===s?'active':''}" data-size="${s}" aria-pressed="${o.size===s}">${s}</button>`).join('')}</div></div><div class="cta-row"><button class="primary" data-add="${p.id}">Add to bag · ${money(p.price)} ${icon('bag')}</button><button class="icon-btn" data-save="${p.id}" aria-label="${state.wishlist.includes(p.id)?'Remove':'Save'} ${p.name}" aria-pressed="${state.wishlist.includes(p.id)}">${state.wishlist.includes(p.id)?'♥':'♡'}</button></div><p class="stock">● In stock · ${p.stock} available in this demo</p><div class="detail-facts"><div><strong>Thoughtful details</strong><br>${p.material}<br>${p.detail}</div><div><strong>A little peace of mind</strong><br>14-day returns<br>Free shipping over ₹3,000</div></div>${productReviewSection(p)}`;}
function summary(t=totals()){return `<div class="summary"><h3>Order summary</h3><div class="summary-line"><span>Subtotal</span><span>${money(t.subtotal)}</span></div>${t.discount?`<div class="summary-line discount"><span>FIRST10 · 10% off</span><span>− ${money(t.discount)}</span></div>`:''}<div class="summary-line"><span>Delivery</span><span>${t.shipping?money(t.shipping):'Free'}</span></div><div class="summary-line total"><span>Total</span><span>${money(t.total)}</span></div><p class="micro">All demo prices include taxes.</p></div>`;}
function cart(){if(!state.cart.length)return empty('♧','Your bag is waiting','Good things take a little exploring. Find your next everyday favourite.');const t=totals();return `<h1>Your bag <span style="font-size:16px;color:var(--muted)">(${cartCount()})</span></h1><p class="intro">A few good things, just for you.</p>${state.cart.map((x,index)=>{const p=product(x.id);return `<article class="cart-item"><a href="#product/${p.id}"><img src="assets/${p.id}.jpg" alt="${p.name}"></a><div class="cart-details"><h3>${p.name}</h3><p>${escapeHtml(x.color)} · ${escapeHtml(x.size)}</p><div class="prices">${money(p.price*x.qty)}</div><div class="cart-actions"><div class="qty"><button data-qty="${index}" data-delta="-1" aria-label="Decrease quantity of ${p.name}" ${x.qty===1?'disabled':''}>−</button><span aria-label="Quantity">${x.qty}</span><button data-qty="${index}" data-delta="1" aria-label="Increase quantity of ${p.name}" ${state.cart.filter(c=>c.id===p.id).reduce((n,c)=>n+c.qty,0)>=p.stock?'disabled':''}>+</button></div><button class="remove" data-remove="${index}">Remove</button></div></div></article>`;}).join('')}<div class="offer"><strong>Something good for your first order.</strong><p>${state.coupon?'FIRST10 applied. You’re saving 10%.':'Use FIRST10 for 10% off your demo order.'}</p><form id="coupon-form" class="coupon-row"><label for="coupon" class="visually-hidden">Promo code</label><input id="coupon" name="coupon" placeholder="Promo code" value="${state.coupon}" maxlength="30"><button class="outline" type="submit">${state.coupon?'Update':'Apply'}</button>${state.coupon?'<button class="text-button" type="button" data-action="remove-coupon">Remove</button>':''}</form></div>${t.shipping?`<p class="micro">Add ${money(3000-t.subtotal)} more for free delivery.</p>`:'<p class="stock">✓ Your order qualifies for free delivery.</p>'}${summary()}<a class="primary" href="#checkout">Continue to checkout →</a><p class="micro" style="text-align:center;margin-top:12px">Guest checkout · No account needed</p>`;}
const field=(name,label,type='text',extra='')=>`<label>${label}<input type="${type}" name="${name}" value="${escapeHtml(state.checkout[name])}" ${extra} required></label>`;
function checkout(){if(!state.cart.length)return empty('♧','Your bag is empty','Add an essential before you check out.');if(checkoutStep==='address'){return `<h1>Make it yours.</h1><p class="intro">A simple checkout. No account needed.</p><div class="stepper"><strong>01 · Delivery</strong><i></i><span>02 · Payment</span><i></i><span>03 · Done</span></div><h3>Where should it go?</h3><form id="address-form" class="checkout-form">${field('name','Full name','text','autocomplete="name" minlength="2" maxlength="70"')}${field('email','Email address','email','autocomplete="email" maxlength="120"')}${field('phone','Mobile number','tel','autocomplete="tel" inputmode="numeric" pattern="[6-9][0-9]{9}" placeholder="10-digit Indian mobile number" maxlength="10" title="Enter a 10-digit Indian mobile number starting with 6–9"')}${field('address','Street address','text','autocomplete="street-address" minlength="5" maxlength="180"')}<div class="field-pair">${field('city','City','text','autocomplete="address-level2" minlength="2" maxlength="60"')}${field('pin','PIN code','text','autocomplete="postal-code" inputmode="numeric" pattern="[1-9][0-9]{5}" maxlength="6" title="Enter a valid 6-digit Indian PIN code"')}</div><div class="form-note">Use sample details for testing. Your address stays in this browser.</div><button class="outline small" type="button" data-action="sample-address">Fill sample details</button>${summary()}<button class="primary" type="submit">Continue to payment →</button></form>`;}return `<h1>One last step.</h1><p class="intro">Review the details. Then you’re all set.</p><div class="stepper"><span>✓ · Delivery</span><i></i><strong>02 · Payment</strong><i></i><span>03 · Done</span></div><div class="address-review"><div class="section-head"><strong>Delivering to</strong><button class="text-button" data-action="edit-address">Edit</button></div><strong>${escapeHtml(state.checkout.name)}</strong><br>${escapeHtml(state.checkout.address)}<br>${escapeHtml(state.checkout.city)} · ${escapeHtml(state.checkout.pin)}<br>${escapeHtml(state.checkout.phone)}</div><div class="section-head"><h3>How would you like to pay?</h3></div><form id="payment-form"><div class="payment-options">${[['upi','UPI','Simulated UPI payment'],['card','Debit / credit card','Simulated card payment'],['cod','Cash on delivery','Demo cash on delivery']].map(([value,label,note])=>`<label class="payment-option"><input type="radio" name="payment" value="${value}" ${state.payment===value?'checked':''} required><span>${label}<small>${note}</small></span></label>`).join('')}</div><div class="form-note">This is a testing prototype. No money is charged and no financial details are collected.</div>${summary()}<button class="primary" type="submit" ${busy?'disabled':''}>${busy?'Creating demo order…':`Place demo order · ${money(totals().total)}`}</button></form>`;}
function orderItems(o){return o.items.map(x=>`<div class="order-product"><img src="assets/${x.id}.jpg" alt="${product(x.id).name}"><div><strong>${product(x.id).name}</strong><p>${escapeHtml(x.color)} · ${escapeHtml(x.size)} · Qty ${x.qty}</p><strong>${money(x.price*x.qty)}</strong></div></div>`).join('');}
function timeline(o){return `<div class="timeline">${['Placed','Packed','Shipped','Delivered'].map((v,i)=>`<div class="${o.stage>=i?'complete':''}"><i></i>${v}</div>`).join('')}</div>`;}
function confirmation(id){const o=state.orders.find(x=>x.id===id);if(!o)return empty('✓','Order not found','Your saved demo orders are available in Orders.','View orders','orders');return `<div class="confirmation"><div class="success-mark">✓</div><div class="eyebrow">A FEW GOOD THINGS ARE ON THE WAY</div><h1 style="margin-top:12px">Good choice,<br>${escapeHtml(o.customer.name.split(' ')[0])}.</h1><p>Your demo order is confirmed. Thanks for making FORME part of your everyday.</p><span class="order-id">${escapeHtml(o.id)}</span></div>${purchaseReviewPrompt(o)}<div class="order-card">${orderItems(o)}${timeline(o)}<p class="micro">Delivery estimate: ${escapeHtml(o.eta)} · Simulation only</p></div>${summary(o.totals)}<a class="primary" href="#orders">Track demo order →</a><a class="outline" style="display:block;text-align:center;margin-top:10px" href="#shop">Keep exploring</a>`;}
function orders(){if(!state.orders.length)return empty('⌑','Good things are coming','Your demo orders will appear here after checkout.');return `<h1>Your good things.</h1><p class="intro">Follow every step of your demo order.</p>${state.orders.slice().reverse().map(o=>`<article class="order-card"><div class="section-head" style="margin:0"><strong>${escapeHtml(o.id)}</strong><span class="detail-badge" style="margin:0">${['Placed','Packed','Shipped','Delivered'][o.stage]}</span></div><p class="micro">${new Date(o.created).toLocaleDateString('en-IN')} · ${money(o.totals.total)}</p>${orderItems(o)}${timeline(o)}${orderReviewActions(o)}<p class="micro">Deliver to ${escapeHtml(o.customer.city)} · ${escapeHtml(o.customer.pin)}</p>${o.stage<3?`<button class="outline small" style="width:100%;margin-top:15px" data-advance="${escapeHtml(o.id)}">Simulate ${['packing','shipping','delivery'][o.stage]} →</button>`:'<p class="stock">✓ Demo workflow completed</p>'}<button class="text-button" style="margin-top:15px" data-receipt="${escapeHtml(o.id)}">Download demo receipt ↓</button></article>`).join('')}`;}

// Customer product reviews are independent from stakeholder design decisions.
const productReviewsFor=id=>state.productReviews.filter(r=>r.productId===id);
const purchasedOrder=(id,orderId)=>state.orders.find(o=>o.id===orderId&&o.items.some(x=>x.id===id));
const reviewStars=rating=>'★'.repeat(rating)+'☆'.repeat(5-rating);
function reviewCard(r){const verified=!!purchasedOrder(r.productId,r.orderId);return '<article class="customer-review"><div class="section-head"><strong class="customer-stars" aria-label="'+r.rating+' out of 5 stars">'+reviewStars(r.rating)+'</strong><a class="text-button" href="#write-review/'+r.productId+'/'+encodeURIComponent(r.id)+'">Edit review</a></div><h3>'+escapeHtml(r.title)+'</h3><p class="customer-review-body">'+escapeHtml(r.body)+'</p><div class="customer-review-meta"><strong>'+escapeHtml(r.reviewer)+'</strong> · '+new Date(r.updated||r.created).toLocaleDateString('en-IN')+'</div>'+(verified?'<span class="purchase-badge">✓ Demo purchase</span>':'<span class="micro">Local test review</span>')+'</article>';}
function productReviewSection(p){const list=productReviewsFor(p.id);return '<section class="product-review-section"><div class="section-head"><h3>Product reviews</h3><a class="text-button" href="#reviews/'+p.id+'">View all ↗</a></div><p class="micro">'+list.length+' local '+(list.length===1?'review':'reviews')+' · Sample catalog ratings are shown separately.</p>'+(list.length?reviewCard(list.at(-1)):'<p class="muted">Your experience could help someone choose. Be the first to leave a local test review.</p>')+'<a class="outline review-write-button" href="#write-review/'+p.id+'">Write a product review →</a></section>';}
function orderReviewActions(o){return '<div class="order-review-actions">'+[...new Set(o.items.map(x=>x.id))].map(id=>{const saved=state.productReviews.find(r=>r.productId===id&&r.orderId===o.id);return '<a class="text-button" href="#write-review/'+id+'/'+encodeURIComponent(saved?saved.id:o.id)+'">'+(saved?'Edit review':'Review')+' · '+product(id).name+' ↗</a>';}).join('')+'</div>';}
function purchaseReviewPrompt(o){if(o.reviewPromptDismissed)return '<p class="micro">You can review your purchase any time in <a class="text-button" href="#reviews">Reviews ↗</a>.</p>';return '<section class="purchase-review-prompt"><div class="eyebrow">YOUR EXPERIENCE MATTERS</div><h2>How was your purchase?</h2><p>This demo order is placed. Try sharing a product review now, or come back after trying it.</p>'+[...new Set(o.items.map(x=>x.id))].map(id=>{const p=product(id),saved=state.productReviews.find(r=>r.productId===id&&r.orderId===o.id);return '<div class="review-prompt-product"><img src="assets/'+id+'.jpg" alt="'+p.name+'"><div><strong>'+p.name+'</strong><a href="#write-review/'+id+'/'+encodeURIComponent(saved?saved.id:o.id)+'" class="text-button">'+(saved?'Edit your review':'Write a review')+' ↗</a></div></div>';}).join('')+'<button class="text-button" data-action="dismiss-product-prompt" data-order="'+escapeHtml(o.id)+'">Maybe later</button><p class="micro">Reviews stay on this browser for testing.</p></section>';}
function productReviewHub(id){const p=id?product(id):null;if(id&&!p)return empty('☆','Product not found','Choose an essential to read or write a review.','Browse product reviews','reviews');if(p){const list=productReviewsFor(id),avg=list.length?(list.reduce((n,r)=>n+r.rating,0)/list.length).toFixed(1):null;return '<div class="eyebrow">THE EVERYDAY COMMUNITY</div><h1>Product reviews</h1><div class="review-product-heading"><img src="assets/'+p.id+'.jpg" alt="'+p.name+'"><div><h3>'+p.name+'</h3><a class="text-button" href="#product/'+p.id+'">View product ↗</a></div></div><div class="review-stats">'+(avg?'<strong>'+avg+' <span>★</span></strong><p>'+list.length+' local '+(list.length===1?'review':'reviews')+'</p>':'<strong>Be the first.</strong><p>No local product reviews yet.</p>')+'</div><a class="primary" href="#write-review/'+p.id+'">Write a product review →</a><p class="micro">Local testing only. Reviews are separate from stakeholder design feedback.</p><div class="customer-review-list">'+(list.length?list.slice().reverse().map(reviewCard).join(''):'<div class="review-empty"><span>☆</span><h3>Every experience counts.</h3><p>Share what you liked and what could be better.</p></div>')+'</div><a class="outline review-write-button" href="#reviews">All product reviews</a>';}
return '<div class="eyebrow">THE EVERYDAY COMMUNITY</div><h1>Good things.<br>Honest reviews.</h1><p class="intro">A space for your product experiences.</p><div class="review-hub-note">Browse an essential, read local feedback, or write your own. Purchased products get a demo purchase badge.</div>'+PRODUCTS.map(p=>{const count=productReviewsFor(p.id).length;return '<article class="review-hub-card"><img src="assets/'+p.id+'.jpg" alt="'+p.name+'"><div><h3>'+p.name+'</h3><p>'+count+' local '+(count===1?'review':'reviews')+'</p><div class="review-hub-actions"><a class="text-button" href="#reviews/'+p.id+'">Read reviews ↗</a><a class="text-button" href="#write-review/'+p.id+'">Write review ↗</a></div></div></article>';}).join('')+'<p class="micro">All reviews are saved only in this browser. Demo ratings in the catalog are not customer submissions.</p>';}
function writeProductReview(id,context){const p=product(id);if(!p)return empty('☆','Product not found','Choose a product from the Reviews area.','Browse reviews','reviews');const edited=context?.startsWith('PR-')?state.productReviews.find(r=>r.id===context&&r.productId===id):null;const order=context?.startsWith('FM-')?purchasedOrder(id,context):edited?purchasedOrder(id,edited.orderId):!context?state.orders.slice().reverse().find(o=>o.items.some(x=>x.id===id)):null;if(context&&!edited&&!order)return empty('☆','Review link not found','You can still leave a review from the product review area.','Back to product reviews','reviews/'+id);const existing=edited||(order?state.productReviews.find(r=>r.orderId===order.id&&r.productId===id):null);return '<div class="eyebrow">SHARE YOUR EVERYDAY</div><h1>'+(existing?'Edit your review.':'How did it feel?')+'</h1><p class="intro">A little feedback goes a long way.</p><div class="review-product-heading"><img src="assets/'+p.id+'.jpg" alt="'+p.name+'"><div><h3>'+p.name+'</h3>'+(order?'<span class="purchase-badge">✓ Demo purchase</span>':'<span class="micro">Local test review</span>')+'</div></div><form id="product-review-form" class="product-review-form" data-product="'+id+'" data-edit="'+(existing?escapeHtml(existing.id):'')+'" data-order="'+(order?escapeHtml(order.id):'')+'"><fieldset class="rating-picker"><legend>Your rating</legend><div class="rating-options">'+[1,2,3,4,5].map(n=>'<label><input type="radio" name="rating" value="'+n+'" '+(existing?.rating===n?'checked':'')+' required><span aria-hidden="true">★</span><small>'+n+'</small><span class="visually-hidden">'+n+' '+(n===1?'star':'stars')+'</span></label>').join('')+'</div><p class="micro">1 · Not for me &nbsp; / &nbsp; 5 · Love it</p></fieldset><label>Your name<input name="reviewer" autocomplete="name" maxlength="60" minlength="2" required placeholder="e.g. Alex (demo reviewer)" value="'+escapeHtml(existing?.reviewer||order?.customer.name||'')+'"></label><label>Review title<input name="title" maxlength="80" minlength="3" required placeholder="Give your review a short title" value="'+escapeHtml(existing?.title||'')+'"></label><label>Your product experience<textarea name="body" rows="4" maxlength="1000" minlength="10" required placeholder="What worked for you? What could be better?">'+escapeHtml(existing?.body||'')+'</textarea></label><p class="form-note">This is a product review simulation. Your review stays in this testing browser and is not sent to anyone.</p><button class="primary" type="submit">'+(existing?'Save review changes':'Save product review')+' ↗</button><a class="outline review-write-button" href="#reviews/'+id+'">Cancel & view reviews</a></form>';}
function submitProductReview(f){if(!f.reportValidity())return;const p=product(f.dataset.product);if(!p)return;const data=Object.fromEntries(new FormData(f)),rating=Number(data.rating);for(const key of ['reviewer','title','body'])data[key]=String(data[key]||'').trim();if(!Number.isInteger(rating)||rating<1||rating>5){toast('Choose a rating from 1 to 5 stars.');return;}for(const [key,min,message]of [['reviewer',2,'Enter a name with at least 2 characters.'],['title',3,'Add a title with at least 3 characters.'],['body',10,'Share at least 10 characters about the product.']]){if(data[key].length<min){f.elements[key].setCustomValidity(message);f.elements[key].reportValidity();return;}}const existing=state.productReviews.find(r=>r.id===f.dataset.edit&&r.productId===p.id);const now=new Date().toISOString(),order=purchasedOrder(p.id,f.dataset.order);const review={id:existing?.id||'PR-'+Date.now().toString(36).toUpperCase()+'-'+Math.random().toString(36).slice(2,7),productId:p.id,reviewer:data.reviewer,title:data.title,body:data.body,rating,orderId:order?.id||null,created:existing?.created||now,updated:existing?now:null};if(existing)state.productReviews[state.productReviews.indexOf(existing)]=review;else state.productReviews.push(review);save();navigate('reviews/'+p.id);toast(existing?'Your product review has been updated.':'Thanks! Your product review is saved locally.');}
app.addEventListener('input',e=>{if(e.target.form?.id==='product-review-form')e.target.setCustomValidity('');});

function route(){const [name,id,context]=(location.hash.slice(1)||'home').split('/');return{name,id,context};}
function render(preserveScroll=false){const r=route();if(r.name==='checkout'&&lastRenderedRoute!=='checkout')checkoutStep='address';lastRenderedRoute=r.name;let name=r.name,body;if(name==='home')body=home();else if(name==='shop')body=catalog();else if(name==='product')body=detail(product(r.id));else if(name==='cart')body=cart();else if(name==='checkout')body=checkout();else if(name==='confirmation')body=confirmation(r.id);else if(name==='orders')body=orders();else if(name==='reviews')body=productReviewHub(r.id);else if(name==='write-review')body=writeProductReview(r.id,r.context);else if(name==='wishlist')body=state.wishlist.length?`<h1>Your favourites.</h1><p class="intro" style="margin-bottom:20px">A little collection of things you love.</p><div class="product-grid">${PRODUCTS.filter(p=>state.wishlist.includes(p.id)).map(card).join('')}</div>`:empty('♡','Keep the good things','Tap a heart to save an essential for later.');else{body=empty('↗','Let’s get you home','This page isn’t part of the prototype.','Back to home','home');name='home';}const scroll=document.querySelector(".app-content")?.scrollTop||0;phone.dataset.theme=state.theme;app.innerHTML=header(['home','shop','wishlist','orders','reviews'].includes(name)?'':({cart:'Your bag',checkout:'Checkout',confirmation:'Order confirmed',product:'Product details','write-review':'Write a review'}[name]||''),name==='product'?'shop':name==='write-review'?'reviews/'+(r.id||''):name==='checkout'?'cart':'home')+`<div class="app-content">${body}</div>`+nav(name==='write-review'?'reviews':name);document.querySelector(".app-content").scrollTop=preserveScroll?scroll:0;renderReviews();document.title=`FORME · ${name[0].toUpperCase()+name.slice(1)} · Local Prototype`;}
function navigate(hash){if(location.hash==='#'+hash)render();else location.hash=hash;}
function renderReviews(){document.querySelectorAll('[data-theme]').forEach(b=>{if(b===phone)return;b.classList.toggle('active',b.dataset.theme===state.theme);b.setAttribute('aria-pressed',b.dataset.theme===state.theme);});const relevant=state.reviews.filter(r=>r.theme===state.theme&&r.decision!=='comment');const latest=relevant.at(-1);const status=document.getElementById('decision-status');status.textContent=latest?(latest.decision==='approved'?'Approved by '+latest.reviewer:'Changes requested'):'Awaiting feedback';status.className=latest?.decision||'';document.getElementById('reviews').innerHTML=state.reviews.length?state.reviews.slice().reverse().map(r=>`<article class="review-entry"><strong>${escapeHtml(r.reviewer)} · ${r.decision==='approved'?'Approved':r.decision==='changes'?'Changes requested':'Feedback'}</strong><small>${r.theme==='calm'?'A · Calm':'B · Bold'} / ${escapeHtml(r.screen)} / ${new Date(r.created).toLocaleString('en-IN')}</small><p>${escapeHtml(r.feedback||'Approved without additional comments.')}</p></article>`).join(''):'<p class="no-reviews">No decisions yet. Your review starts here.</p>';document.getElementById('export-reviews').disabled=!state.reviews.length;}
function download(name,content,type){const form=document.createElement('form');form.method='POST';form.action='/download';form.style.display='none';for(const [key,value]of Object.entries({filename:name,content})){const input=document.createElement('input');input.type='hidden';input.name=key;input.value=value;form.appendChild(input);}document.body.appendChild(form);form.submit();form.remove();}
app.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const p=product(route().id);if(b.dataset.save){const id=b.dataset.save;const had=state.wishlist.includes(id);state.wishlist=had?state.wishlist.filter(x=>x!==id):[...state.wishlist,id];save();render(true);toast(had?'Removed from saved essentials.':'Saved for a little later.');}else if(b.dataset.category){shop.category=b.dataset.category;render(true);}else if(b.dataset.color&&p){detailOptions[p.id].color=b.dataset.color;render(true);}else if(b.dataset.size&&p){detailOptions[p.id].size=b.dataset.size;render(true);}else if(b.dataset.add){const item=product(b.dataset.add),o=detailOptions[item.id];if(!o?.size){toast('Choose your size to add this essential.');return;}const total=state.cart.filter(x=>x.id===item.id).reduce((n,x)=>n+x.qty,0);if(total>=item.stock){toast('You’ve reached the available quantity for this product.');return;}const existing=state.cart.find(x=>lineKey(x)===lineKey({id:item.id,...o}));if(existing)existing.qty++;else state.cart.push({id:item.id,color:o.color,size:o.size,qty:1});save();render(true);toast('A good choice. Added to your bag.');}else if(b.dataset.qty!==undefined){const x=state.cart[+b.dataset.qty];if(!x)return;const next=x.qty+Number(b.dataset.delta);const total=state.cart.filter(c=>c.id===x.id).reduce((n,c)=>n+c.qty,0);if(next>=1&&(b.dataset.delta==='-1'||total<product(x.id).stock)){x.qty=next;save();render(true);}}else if(b.dataset.remove!==undefined){state.cart.splice(+b.dataset.remove,1);if(!state.cart.length)state.coupon='';save();render(true);toast('Removed from your bag.');}else if(b.dataset.advance){const o=state.orders.find(x=>x.id===b.dataset.advance);if(o&&o.stage<3){o.stage++;save();render(true);toast('Demo order moved to '+['placed','packed','shipped','delivered'][o.stage]+'.');}}else if(b.dataset.action==='dismiss-product-prompt'){const o=state.orders.find(x=>x.id===b.dataset.order);if(o){o.reviewPromptDismissed=true;save();render(true);toast('Review whenever you like from Reviews or Orders.');}}else if(b.dataset.receipt){const o=state.orders.find(x=>x.id===b.dataset.receipt);download(o.id+'-demo-receipt.txt',`FORME · DEMO RECEIPT\nSimulation only — no payment was charged.\n\nOrder: ${o.id}\n${o.items.map(x=>`${product(x.id).name} · ${x.color} · ${x.size} · ${x.qty} × ${money(x.price)}`).join('\n')}\n\nSubtotal: ${money(o.totals.subtotal)}\nDiscount: ${money(o.totals.discount)}\nDelivery: ${money(o.totals.shipping)}\nTotal: ${money(o.totals.total)}\nPayment: ${o.payment} (simulated)\n`, 'text/plain');toast('Demo receipt downloaded.');}else if(b.dataset.action==='sample-address'){const sample={name:'Alex Morgan',email:'alex@example.com',phone:'9876543210',address:'12 Sample Street, Green Park',city:'Chennai',pin:'600001'};Object.entries(sample).forEach(([k,v])=>document.querySelector(`#address-form [name="${k}"]`).value=v);}else if(b.dataset.action==='edit-address'){checkoutStep='address';render();}else if(b.dataset.action==='remove-coupon'){state.coupon='';save();render(true);}else if(b.dataset.action==='clear-filters'){shop={q:'',category:'All',sort:'featured'};render();}else if(b.dataset.action==='explore'){shop={q:'',category:'All',sort:'featured'};navigate('shop');}});
app.addEventListener('change',e=>{if(e.target.id==='sort'){shop.sort=e.target.value;render(true);}if(e.target.form?.id==='address-form'){state.checkout[e.target.name]=e.target.value;save();}});
app.addEventListener('submit',async e=>{e.preventDefault();const f=e.target;if(f.id==='search-form'){shop.q=new FormData(f).get('q').trim();navigate('shop');}else if(f.id==='coupon-form'){const code=new FormData(f).get('coupon').trim().toUpperCase();if(code!=='FIRST10'){toast('Try FIRST10 for 10% off. That code isn’t available.');return;}state.coupon=code;save();render(true);toast('FIRST10 applied. A little treat, on us.');}else if(f.id==='address-form'){if(!f.reportValidity())return;state.checkout=Object.fromEntries(new FormData(f));for(const k of Object.keys(state.checkout))state.checkout[k]=state.checkout[k].trim();if(state.checkout.name.length<2||state.checkout.address.length<5||state.checkout.city.length<2){toast('Please enter a complete name and delivery address.');return;}save();checkoutStep='payment';render();}else if(f.id==='product-review-form'){submitProductReview(f);}else if(f.id==='payment-form'){if(busy||!state.cart.length)return;if(!state.checkout.name||!state.checkout.address){checkoutStep='address';render();return;}busy=true;state.payment=new FormData(f).get('payment');render(true);const t=totals(), date=new Date();const eta=new Date(date.getTime()+4*86400000).toLocaleDateString('en-IN',{day:'numeric',month:'short'});const o={id:'FM-'+date.getTime().toString(36).toUpperCase(),created:date.toISOString(),items:state.cart.map(x=>({...x,price:product(x.id).price})),totals:t,customer:{...state.checkout},payment:state.payment,eta,stage:0};state.orders.push(o);state.cart=[];state.coupon='';save();busy=false;checkoutStep='address';navigate('confirmation/'+o.id);}});
document.querySelectorAll('button[data-theme]').forEach(b=>b.addEventListener('click',()=>{state.theme=b.dataset.theme;save();render(true);}));
document.getElementById('review-form').addEventListener('submit',e=>{e.preventDefault();const f=e.target;if(!f.reportValidity())return;const data=Object.fromEntries(new FormData(f));data.reviewer=data.reviewer.trim();data.feedback=data.feedback.trim();if(!data.reviewer){toast('Enter your name to record a review.');return;}if(data.decision!=='approved'&&!data.feedback){f.elements.feedback.setCustomValidity('Add your feedback so the team can act on it.');f.elements.feedback.reportValidity();return;}const {name,id}=route();state.reviews.push({...data,theme:state.theme,screen:name+(id?'/'+id:''),created:new Date().toISOString()});save();f.elements.feedback.value='';renderReviews();toast('Review saved on this browser.');});
document.querySelector('#review-form textarea').addEventListener('input',e=>e.target.setCustomValidity(''));
document.querySelector('#review-form select').addEventListener('change',()=>document.querySelector('#review-form textarea').setCustomValidity(''));
document.getElementById('export-reviews').addEventListener('click',()=>{if(!state.reviews.length)return;download('forme-stakeholder-reviews.json',JSON.stringify({project:'FORME · Experiment 3',exported:new Date().toISOString(),storage:'Browser-local testing session',reviews:state.reviews},null,2),'application/json');toast('Review log exported.');});
document.getElementById('toggle-review').addEventListener('click',()=>{document.getElementById('review-panel').classList.add('open');document.querySelector('#review-form input').focus();});
document.getElementById('close-review').addEventListener('click',()=>{document.getElementById('review-panel').classList.remove('open');document.getElementById('toggle-review').focus();});
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.getElementById('review-panel').classList.remove('open');});
const resetDialog=document.getElementById('reset-dialog');document.getElementById('reset-demo').addEventListener('click',()=>resetDialog.showModal());document.getElementById('cancel-reset').addEventListener('click',()=>resetDialog.close());document.getElementById('confirm-reset').addEventListener('click',()=>{resetDialog.close();state=freshState();shop={q:'',category:'All',sort:'featured'};detailOptions={};checkoutStep='address';save();document.getElementById('review-form').reset();document.getElementById('review-panel').classList.remove('open');navigate('home');toast('A fresh testing session is ready.');});
window.addEventListener('hashchange',()=>render());
render();
